n = int(input())
s = input()
first1 = n
for i in range(len(s)):
	if s[i] == '1':
		first1 = i
		break
s = s[first1:]
if s == '':
	print(0)
else:
	first0 = n
	for i in range(len(s)):
		if s[i] == '0':
			first0 = i
			break
	if first0 == n:
		print(s)
	else:
		n = int(s, 2)
		best = n
		for i in range(first0 + 1):
			best = max(best, n | n >> i)
		print(bin(best)[2:])
print()
